import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../core/app_state.dart';import 'compress_screen.dart';import 'decompress_screen.dart';import 'history_screen.dart';import 'receive_screen.dart';import 'settings_screen.dart';
class AppShell extends StatelessWidget{const AppShell({super.key});@override Widget build(BuildContext c){final s=c.watch<AppState>();final pages=[const CompressScreen(),const DecompressScreen(),const HistoryScreen(),const ReceiveScreen(),const SettingsScreen()];return Scaffold(body:Row(children:[NavigationRail(extended:MediaQuery.sizeOf(c).width>1100,selectedIndex:s.page,onDestinationSelected:s.setPage,leading:const Padding(padding:EdgeInsets.symmetric(vertical:18),child:CircleAvatar(radius:23,child:Text('XC'))),destinations:const[NavigationRailDestination(icon:Icon(Icons.compress),label:Text('Compress')),NavigationRailDestination(icon:Icon(Icons.unarchive),label:Text('Decompress')),NavigationRailDestination(icon:Icon(Icons.history),label:Text('History')),NavigationRailDestination(icon:Icon(Icons.download),label:Text('Receive')),NavigationRailDestination(icon:Icon(Icons.settings),label:Text('Settings'))]),const VerticalDivider(width:1),Expanded(child:pages[s.page])])) ;}}
